-- =====================================================================
--  CLÍNICA DERMATOLÓGICA DERMAVIDA - DATOS INICIALES (SEED)
--  Las fechas de las citas se calculan relativas al día actual
--  para que el sistema siempre muestre información vigente.
-- =====================================================================

-- Función auxiliar temporal: devuelve el n-ésimo día laborable (lun-sáb)
-- n >= 0: hacia adelante desde hoy | n < 0: hacia atrás desde hoy
CREATE OR REPLACE FUNCTION tmp_dia_habil(n INT) RETURNS DATE AS $$
DECLARE d DATE := CURRENT_DATE; k INT := 0;
BEGIN
  IF n >= 0 THEN
    IF EXTRACT(DOW FROM d) = 0 THEN d := d + 1; END IF;
    WHILE k < n LOOP d := d + 1; IF EXTRACT(DOW FROM d) <> 0 THEN k := k + 1; END IF; END LOOP;
  ELSE
    WHILE k < -n LOOP d := d - 1; IF EXTRACT(DOW FROM d) <> 0 THEN k := k + 1; END IF; END LOOP;
  END IF;
  RETURN d;
END $$ LANGUAGE plpgsql;

